import crypto from 'node:crypto';
import { promisify } from 'node:util';

const scryptAsync = promisify(crypto.scrypt);

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

export interface UserRecord {
  id: string;
  email: string;
  passwordHash: string;
  role: string;
}

interface RateLimitRecord {
  attempts: number;
  lockoutUntil: number;
  firstAttemptAt: number;
}

export class AuthService implements IAuthService {
  private readonly jwtSecret: string;
  private readonly maxFailedAttempts: number;
  private readonly lockoutWindowMs: number;
  private readonly attemptWindowMs: number;
  private readonly users: Map<string, UserRecord> = new Map();
  private readonly rateLimits: Map<string, RateLimitRecord> = new Map();

  // Pre-computed dummy hash used to neutralize timing attacks during unknown user authentication
  private dummyHash: string = '';

  constructor(options?: {
    jwtSecret?: string;
    maxFailedAttempts?: number;
    attemptWindowMs?: number;
    lockoutWindowMs?: number;
    initialUsers?: UserRecord[];
  }) {
    this.jwtSecret = options?.jwtSecret || process.env.JWT_SECRET || 'secure_production_fallback_key_32chars_min!!';
    this.maxFailedAttempts = options?.maxFailedAttempts ?? 5;
    this.attemptWindowMs = options?.attemptWindowMs ?? 60_000; // 1 minute window
    this.lockoutWindowMs = options?.lockoutWindowMs ?? 900_000; // 15 minutes lockout

    if (options?.initialUsers) {
      for (const user of options.initialUsers) {
        this.users.set(user.email.toLowerCase(), user);
      }
    }

    // Initialize dummy hash synchronously to avoid uninitialized state
    const dummySalt = crypto.randomBytes(16).toString('hex');
    const dummyDerived = crypto.scryptSync('dummy_timing_padding_secret', dummySalt, 64, {
      N: 16384,
      r: 8,
      p: 1,
      maxmem: 32 * 1024 * 1024,
    });
    this.dummyHash = `${dummySalt}:${dummyDerived.toString('hex')}`;
  }

  public registerUser(user: UserRecord): void {
    this.users.set(user.email.toLowerCase(), user);
  }

  public async hashPassword(password: string): Promise<string> {
    if (!password || typeof password !== 'string') {
      throw new Error('Password must be a non-empty string');
    }
    const salt = crypto.randomBytes(16).toString('hex');
    const derivedKey = (await scryptAsync(password, salt, 64, {
      N: 16384,
      r: 8,
      p: 1,
      maxmem: 32 * 1024 * 1024,
    })) as Buffer;

    return `${salt}:${derivedKey.toString('hex')}`;
  }

  public async verifyPassword(password: string, hash: string): Promise<boolean> {
    if (!password || !hash || typeof password !== 'string' || typeof hash !== 'string') {
      return false;
    }

    const parts = hash.split(':');
    if (parts.length !== 2) {
      return false;
    }

    const [salt, storedHashHex] = parts;
    const storedBuffer = Buffer.from(storedHashHex, 'hex');

    try {
      const derivedKey = (await scryptAsync(password, salt, storedBuffer.length, {
        N: 16384,
        r: 8,
        p: 1,
        maxmem: 32 * 1024 * 1024,
      })) as Buffer;

      if (derivedKey.length !== storedBuffer.length) {
        return false;
      }

      return crypto.timingSafeEqual(derivedKey, storedBuffer);
    } catch {
      return false;
    }
  }

  public async generateToken(
    payload: { id: string; email: string; role?: string },
    secret: string
  ): Promise<string> {
    if (!payload || !payload.id || !payload.email) {
      throw new Error('Payload must contain valid id and email');
    }
    const effectiveSecret = secret || this.jwtSecret;

    const header = {
      alg: 'HS256',
      typ: 'JWT',
    };

    const now = Math.floor(Date.now() / 1000);
    const tokenPayload = {
      sub: payload.id,
      email: payload.email,
      role: payload.role || 'user',
      iat: now,
      exp: now + 900, // 15-minute standard expiration
    };

    const encodedHeader = Buffer.from(JSON.stringify(header)).toString('base64url');
    const encodedPayload = Buffer.from(JSON.stringify(tokenPayload)).toString('base64url');
    const dataToSign = `${encodedHeader}.${encodedPayload}`;

    const signature = crypto
      .createHmac('sha256', effectiveSecret)
      .update(dataToSign)
      .digest('base64url');

    return `${dataToSign}.${signature}`;
  }

  public async handleLogin(request: {
    email?: string;
    password?: string;
    ip?: string;
  }): Promise<{ status: number; body: any }> {
    try {
      const { email, password, ip = '127.0.0.1' } = request;

      // 1. Strict Input Validation
      if (!email || !password || typeof email !== 'string' || typeof password !== 'string') {
        return {
          status: 400,
          body: {
            error: 'BAD_REQUEST',
            message: 'Email and password are required',
          },
        };
      }

      const normalizedEmail = email.trim().toLowerCase();
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(normalizedEmail)) {
        return {
          status: 400,
          body: {
            error: 'BAD_REQUEST',
            message: 'Invalid email address format',
          },
        };
      }

      // 2. Dual-Key Rate Limiting & Brute-Force Defense (IP + Email)
      const ipLimitKey = `ip:${ip}`;
      const accountLimitKey = `acc:${normalizedEmail}`;

      if (this.isRateLimited(ipLimitKey) || this.isRateLimited(accountLimitKey)) {
        return {
          status: 429,
          body: {
            error: 'TOO_MANY_REQUESTS',
            message: 'Too many authentication attempts. Please try again later.',
          },
        };
      }

      // 3. User Lookup & Timing-Safe Verification
      const user = this.users.get(normalizedEmail);
      const targetHash = user ? user.passwordHash : this.dummyHash;
      const isValidPassword = await this.verifyPassword(password, targetHash);

      if (!user || !isValidPassword) {
        this.recordFailedAttempt(ipLimitKey);
        this.recordFailedAttempt(accountLimitKey);

        return {
          status: 401,
          body: {
            error: 'UNAUTHORIZED',
            message: 'Invalid email or password',
          },
        };
      }

      // 4. Reset Rate Limits on Successful Login
      this.clearRateLimit(ipLimitKey);
      this.clearRateLimit(accountLimitKey);

      // 5. Generate Short-Lived Access Token
      const token = await this.generateToken(
        {
          id: user.id,
          email: user.email,
          role: user.role,
        },
        this.jwtSecret
      );

      return {
        status: 200,
        body: {
          token,
          user: {
            id: user.id,
            email: user.email,
            role: user.role,
          },
        },
      };
    } catch {
      // Catch unexpected errors to prevent internal leakage and return generic response
      return {
        status: 500,
        body: {
          error: 'INTERNAL_SERVER_ERROR',
          message: 'An internal error occurred during authentication',
        },
      };
    }
  }

  private isRateLimited(key: string): boolean {
    const record = this.rateLimits.get(key);
    if (!record) return false;

    const now = Date.now();

    if (record.lockoutUntil > now) {
      return true;
    }

    if (now - record.firstAttemptAt > this.attemptWindowMs) {
      this.rateLimits.delete(key);
      return false;
    }

    return record.attempts >= this.maxFailedAttempts;
  }

  private recordFailedAttempt(key: string): void {
    const now = Date.now();
    const record = this.rateLimits.get(key);

    if (!record || now - record.firstAttemptAt > this.attemptWindowMs) {
      this.rateLimits.set(key, {
        attempts: 1,
        firstAttemptAt: now,
        lockoutUntil: 0,
      });
      return;
    }

    record.attempts += 1;
    if (record.attempts >= this.maxFailedAttempts) {
      record.lockoutUntil = now + this.lockoutWindowMs;
    }
  }

  private clearRateLimit(key: string): void {
    this.rateLimits.delete(key);
  }
}

