export class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class InvariantViolationError extends DomainError {}
export class CurrencyMismatchError extends DomainError {}

export class Money {
  readonly amount: number;
  readonly currency: string;

  constructor(amount: number, currency: string) {
    if (!Number.isFinite(amount)) {
      throw new InvariantViolationError('Money amount must be a finite number');
    }
    if (!currency || currency.trim().length === 0) {
      throw new InvariantViolationError('Currency must be specified');
    }
    this.amount = Math.round(amount * 100) / 100;
    this.currency = currency.toUpperCase().trim();
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (this.currency !== other.currency) {
      throw new CurrencyMismatchError(
        `Cannot add Money with currency ${other.currency} to Money with currency ${this.currency}`
      );
    }
    return new Money(
      Math.round((this.amount + other.amount) * 100) / 100,
      this.currency
    );
  }

  multiply(factor: number): Money {
    if (!Number.isFinite(factor)) {
      throw new InvariantViolationError('Factor must be a finite number');
    }
    return new Money(
      Math.round(this.amount * factor * 100) / 100,
      this.currency
    );
  }

  equals(other: Money): boolean {
    return this.amount === other.amount && this.currency === other.currency;
  }
}

export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export interface OrderItem {
  readonly itemId: string;
  readonly quantity: number;
  readonly unitPrice: Money;
}

export interface DomainEvent {
  readonly eventId: string;
  readonly occurredOn: Date;
  readonly eventName: string;
  readonly aggregateId: string;
  readonly payload: Record<string, unknown>;
}

export class Order {
  readonly id: string;
  readonly customerId: string;
  private _status: OrderStatus;
  private readonly _items: Map<string, OrderItem>;
  private _domainEvents: DomainEvent[];

  constructor(id: string, customerId: string) {
    if (!id || id.trim().length === 0) {
      throw new InvariantViolationError('Order ID must be provided');
    }
    if (!customerId || customerId.trim().length === 0) {
      throw new InvariantViolationError('Customer ID must be provided');
    }

    this.id = id.trim();
    this.customerId = customerId.trim();
    this._status = 'PENDING';
    this._items = new Map<string, OrderItem>();
    this._domainEvents = [];

    this.recordDomainEvent('OrderCreated', {
      orderId: this.id,
      customerId: this.customerId,
      status: this._status,
    });
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return Array.from(this._items.values());
  }

  addItem(itemId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new InvariantViolationError(
        `Cannot add items to an order in '${this._status}' status`
      );
    }
    if (!itemId || itemId.trim().length === 0) {
      throw new InvariantViolationError('Item ID must be provided');
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new InvariantViolationError('Quantity must be a positive integer');
    }
    if (price.amount < 0) {
      throw new InvariantViolationError('Price cannot be negative');
    }

    const trimmedItemId = itemId.trim();
    const existingItem = this._items.get(trimmedItemId);

    if (existingItem) {
      if (!existingItem.unitPrice.equals(price)) {
        throw new InvariantViolationError(
          `Cannot change unit price of existing item '${trimmedItemId}' from ${existingItem.unitPrice.amount} ${existingItem.unitPrice.currency} to ${price.amount} ${price.currency}`
        );
      }
      this._items.set(trimmedItemId, {
        itemId: trimmedItemId,
        quantity: existingItem.quantity + quantity,
        unitPrice: existingItem.unitPrice,
      });
    } else {
      if (this._items.size > 0) {
        const firstItem = this._items.values().next().value;
        if (firstItem && firstItem.unitPrice.currency !== price.currency) {
          throw new CurrencyMismatchError(
            `Currency mismatch: Item currency '${price.currency}' does not match order currency '${firstItem.unitPrice.currency}'`
          );
        }
      }
      this._items.set(trimmedItemId, {
        itemId: trimmedItemId,
        quantity,
        unitPrice: price,
      });
    }

    this.recordDomainEvent('OrderItemAdded', {
      orderId: this.id,
      itemId: trimmedItemId,
      quantity,
      unitPrice: { amount: price.amount, currency: price.currency },
    });
  }

  pay(): void {
    if (this._status !== 'PENDING') {
      throw new InvariantViolationError(
        `Cannot pay for order in '${this._status}' status. Only PENDING orders can be paid`
      );
    }
    if (this._items.size === 0) {
      throw new InvariantViolationError('Cannot pay for an order with no items');
    }

    this._status = 'PAID';
    this.recordDomainEvent('OrderPaid', {
      orderId: this.id,
      customerId: this.customerId,
      totalAmount: this.calculateTotal(),
    });
  }

  ship(): void {
    if (this._status !== 'PAID') {
      throw new InvariantViolationError(
        `Cannot ship order in '${this._status}' status. Order must be PAID before shipping`
      );
    }

    this._status = 'SHIPPED';
    this.recordDomainEvent('OrderShipped', {
      orderId: this.id,
      customerId: this.customerId,
    });
  }

  cancel(): void {
    if (this._status === 'SHIPPED') {
      throw new InvariantViolationError('Cannot cancel an order that has already been shipped');
    }
    if (this._status === 'CANCELLED') {
      throw new InvariantViolationError('Order is already cancelled');
    }

    const previousStatus = this._status;
    this._status = 'CANCELLED';
    this.recordDomainEvent('OrderCancelled', {
      orderId: this.id,
      customerId: this.customerId,
      previousStatus,
    });
  }

  calculateTotal(): Money | null {
    if (this._items.size === 0) {
      return null;
    }
    let total: Money | null = null;
    for (const item of this._items.values()) {
      const lineTotal = item.unitPrice.multiply(item.quantity);
      total = total ? total.add(lineTotal) : lineTotal;
    }
    return total;
  }

  getDomainEvents(): any[] {
    return [...this._domainEvents];
  }

  clearDomainEvents(): void {
    this._domainEvents = [];
  }

  private recordDomainEvent(eventName: string, payload: Record<string, unknown>): void {
    this._domainEvents.push({
      eventId: this.generateUUID(),
      occurredOn: new Date(),
      eventName,
      aggregateId: this.id,
      payload,
    });
  }

  private generateUUID(): string {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (char) => {
      const random = (Math.random() * 16) | 0;
      const value = char === 'x' ? random : (random & 0x3) | 0x8;
      return value.toString(16);
    });
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

export class InMemoryOrderRepository implements IOrderRepository {
  private readonly store: Map<string, Order> = new Map();

  async findById(id: string): Promise<Order | null> {
    const order = this.store.get(id);
    return order ? this.cloneOrder(order) : null;
  }

  async save(order: Order): Promise<void> {
    this.store.set(order.id, this.cloneOrder(order));
    order.clearDomainEvents();
  }

  private cloneOrder(order: Order): Order {
    const cloned = new Order(order.id, order.customerId);
    (cloned as { _status: OrderStatus })._status = order.status;
    for (const item of order.items) {
      cloned.addItem(item.itemId, item.quantity, item.unitPrice);
    }
    cloned.clearDomainEvents();
    return cloned;
  }
}

