/**
 * Domain-Driven Design: Order Aggregate Root & Business Invariants
 * Bounded Context: Sales & Ordering
 */

// --- Domain Errors ---

export class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class CurrencyMismatchError extends DomainError {
  constructor(expected: string, actual: string) {
    super(`Currency mismatch: expected ${expected}, got ${actual}`);
  }
}

export class InvalidArgumentError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class InvalidOrderStateError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// --- Value Objects ---

export class Money {
  readonly amount: number;
  readonly currency: string;

  constructor(amount: number, currency: string) {
    if (!Number.isFinite(amount)) {
      throw new InvalidArgumentError('Amount must be a finite number');
    }
    if (amount < 0) {
      throw new InvalidArgumentError('Amount cannot be negative');
    }
    if (!currency || currency.trim().length !== 3) {
      throw new InvalidArgumentError('Currency must be a 3-letter ISO code');
    }

    // Round to 2 decimal places to prevent floating-point anomalies
    this.amount = Math.round(amount * 100) / 100;
    this.currency = currency.toUpperCase().trim();
    Object.freeze(this);
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (this.currency !== other.currency) {
      throw new CurrencyMismatchError(this.currency, other.currency);
    }
    return new Money(this.amount + other.amount, this.currency);
  }

  multiply(factor: number): Money {
    if (!Number.isFinite(factor) || factor < 0) {
      throw new InvalidArgumentError('Factor must be a non-negative finite number');
    }
    return new Money(this.amount * factor, this.currency);
  }

  equals(other: Money): boolean {
    return this.amount === other.amount && this.currency === other.currency;
  }
}

// --- Domain Events ---

export interface IDomainEvent {
  readonly eventId: string;
  readonly occurredAt: Date;
  readonly eventName: string;
  readonly aggregateId: string;
}

export class OrderCreatedEvent implements IDomainEvent {
  readonly eventId: string;
  readonly occurredAt: Date;
  readonly eventName = 'OrderCreated';

  constructor(
    readonly aggregateId: string,
    readonly customerId: string
  ) {
    this.eventId = `${aggregateId}-created-${Date.now()}`;
    this.occurredAt = new Date();
    Object.freeze(this);
  }
}

export class OrderItemAddedEvent implements IDomainEvent {
  readonly eventId: string;
  readonly occurredAt: Date;
  readonly eventName = 'OrderItemAdded';

  constructor(
    readonly aggregateId: string,
    readonly itemId: string,
    readonly quantity: number,
    readonly unitPrice: Money
  ) {
    this.eventId = `${aggregateId}-item-added-${itemId}-${Date.now()}`;
    this.occurredAt = new Date();
    Object.freeze(this);
  }
}

export class OrderPaidEvent implements IDomainEvent {
  readonly eventId: string;
  readonly occurredAt: Date;
  readonly eventName = 'OrderPaid';

  constructor(
    readonly aggregateId: string,
    readonly total: Money
  ) {
    this.eventId = `${aggregateId}-paid-${Date.now()}`;
    this.occurredAt = new Date();
    Object.freeze(this);
  }
}

export class OrderShippedEvent implements IDomainEvent {
  readonly eventId: string;
  readonly occurredAt: Date;
  readonly eventName = 'OrderShipped';

  constructor(readonly aggregateId: string) {
    this.eventId = `${aggregateId}-shipped-${Date.now()}`;
    this.occurredAt = new Date();
    Object.freeze(this);
  }
}

export class OrderCancelledEvent implements IDomainEvent {
  readonly eventId: string;
  readonly occurredAt: Date;
  readonly eventName = 'OrderCancelled';

  constructor(
    readonly aggregateId: string,
    readonly reason: string
  ) {
    this.eventId = `${aggregateId}-cancelled-${Date.now()}`;
    this.occurredAt = new Date();
    Object.freeze(this);
  }
}

// --- Internal Entities ---

export class OrderItem {
  constructor(
    readonly itemId: string,
    readonly quantity: number,
    readonly price: Money
  ) {
    if (!itemId || itemId.trim().length === 0) {
      throw new InvalidArgumentError('Item ID cannot be empty');
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new InvalidArgumentError('Quantity must be a positive integer');
    }
    Object.freeze(this);
  }

  get subtotal(): Money {
    return this.price.multiply(this.quantity);
  }
}

// --- Aggregate Root ---

export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export class Order {
  readonly id: string;
  readonly customerId: string;
  private _status: OrderStatus;
  private _items: OrderItem[] = [];
  private _domainEvents: IDomainEvent[] = [];

  constructor(id: string, customerId: string) {
    if (!id || id.trim().length === 0) {
      throw new InvalidArgumentError('Order ID cannot be empty');
    }
    if (!customerId || customerId.trim().length === 0) {
      throw new InvalidArgumentError('Customer ID cannot be empty');
    }

    this.id = id.trim();
    this.customerId = customerId.trim();
    this._status = 'PENDING';

    this.recordEvent(new OrderCreatedEvent(this.id, this.customerId));
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return Object.freeze([...this._items]);
  }

  get total(): Money | null {
    if (this._items.length === 0) {
      return null;
    }
    return this._items.reduce<Money>((acc, item) => acc.add(item.subtotal), Money.of(0, this._items[0].price.currency));
  }

  addItem(itemId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new InvalidOrderStateError(
        `Cannot add items to order ${this.id} because it is in '${this._status}' status`
      );
    }

    if (this._items.length > 0) {
      const activeCurrency = this._items[0].price.currency;
      if (price.currency !== activeCurrency) {
        throw new CurrencyMismatchError(activeCurrency, price.currency);
      }
    }

    const existingIndex = this._items.findIndex((item) => item.itemId === itemId);
    if (existingIndex >= 0) {
      const existing = this._items[existingIndex];
      const mergedQuantity = existing.quantity + quantity;
      this._items[existingIndex] = new OrderItem(itemId, mergedQuantity, price);
    } else {
      this._items.push(new OrderItem(itemId, quantity, price));
    }

    this.recordEvent(new OrderItemAddedEvent(this.id, itemId, quantity, price));
  }

  pay(): void {
    if (this._status !== 'PENDING') {
      throw new InvalidOrderStateError(
        `Cannot pay for order ${this.id} with status '${this._status}'`
      );
    }
    if (this._items.length === 0) {
      throw new InvalidOrderStateError(`Cannot pay for an empty order ${this.id}`);
    }

    const orderTotal = this.total!;
    this._status = 'PAID';
    this.recordEvent(new OrderPaidEvent(this.id, orderTotal));
  }

  ship(): void {
    if (this._status !== 'PAID') {
      throw new InvalidOrderStateError(
        `Cannot ship order ${this.id} unless it is PAID. Current status: '${this._status}'`
      );
    }

    this._status = 'SHIPPED';
    this.recordEvent(new OrderShippedEvent(this.id));
  }

  cancel(): void {
    if (this._status === 'SHIPPED') {
      throw new InvalidOrderStateError(
        `Cannot cancel order ${this.id} because it has already been SHIPPED`
      );
    }
    if (this._status === 'CANCELLED') {
      throw new InvalidOrderStateError(`Order ${this.id} is already CANCELLED`);
    }

    this._status = 'CANCELLED';
    this.recordEvent(new OrderCancelledEvent(this.id, 'User or system requested cancellation'));
  }

  getDomainEvents(): IDomainEvent[] {
    return [...this._domainEvents];
  }

  clearDomainEvents(): void {
    this._domainEvents = [];
  }

  private recordEvent(event: IDomainEvent): void {
    this._domainEvents.push(event);
  }
}

// --- Repository Contract ---

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

// --- In-Memory Repository Implementation ---

export class InMemoryOrderRepository implements IOrderRepository {
  private readonly store = new Map<string, Order>();

  async findById(id: string): Promise<Order | null> {
    const order = this.store.get(id);
    if (!order) {
      return null;
    }
    return order;
  }

  async save(order: Order): Promise<void> {
    this.store.set(order.id, order);
  }

  async delete(id: string): Promise<void> {
    this.store.delete(id);
  }
}
